using System;using System.Collections;using System.Linq;using System.Reflection;using UnityEngine;using UnityEngine.UI;using UnityEditor;using UnityEditor.SceneManagement;
namespace DragonTower.Editor {
[InitializeOnLoad] public static class ThroneValidation {
 const string Flag="ThroneQA",Key="DragonTower.Test.Throne",Out="C:/Users/PC/Documents/Codex/Throne-20261012/";static CollectionFlow flow;static ContentDatabase db;static BattleSkin skin;static IEnumerator cases;static double next;
 static ThroneValidation(){if(SessionState.GetBool(Flag,false))EditorApplication.update+=Tick;}
 public static void Run(){Environment.SetEnvironmentVariable("DRAGON_TOWER_TEST_SAVE",Key);PlayerPrefs.DeleteKey(Key+".A");PlayerPrefs.DeleteKey(Key+".B");SessionState.SetBool(Flag,true);AssetDatabase.ImportAsset("Assets/Resources/PixelBattleSkin.asset",ImportAssetOptions.ForceUpdate);Debug.Log("SKIN_DUMP "+JsonUtility.ToJson(Resources.Load<BattleSkin>("PixelBattleSkin")));EditorSceneManager.OpenScene("Assets/Scenes/Battle.unity");EditorApplication.EnterPlaymode();}
 static void Check(bool b,string message){if(!b)throw new Exception(message);Debug.Log("THRONE_CHECK "+message);}
 static object Call(string n,params object[] a)=>typeof(CollectionFlow).GetMethod(n,BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.Public).Invoke(flow,a);
 static void Capture(string n)=>typeof(AugmentPresentationValidation).GetMethod("Capture",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{Out+n+".png"});
 static void Assign(TowerRun r)=>typeof(CollectionFlow).GetField("towerRun",BindingFlags.Instance|BindingFlags.NonPublic).SetValue(flow,r);
 static void Set(int floor,TowerRoomKind kind,bool chosen=true){flow.ShowLobby();var d=flow.Session.Selected;var r=new TowerRun(d.maxHP,0,1,d.elementType,d.alternateSkillElement,d.StableId,d);r.AttachInstance(flow.Session.Profile.selectedInstanceId);var s=r.Capture();s.Floor=floor;s.choices=kind==TowerRoomKind.Boss?new[]{kind}:new[]{kind,TowerRoomKind.Gold};r=TowerRun.Restore(s,db);if(chosen)r.BeginFloorRoom(0,18421);Assign(r);}
 static void Scenery(EnvironmentScreen s){var image=UnityEngine.Object.FindObjectsByType<Image>(FindObjectsSortMode.None).First(x=>x.name=="Room scenery"&&x.gameObject.activeInHierarchy);Check(image.sprite==skin.BackgroundForScreen(flow.CurrentRun.Floor,s),"scenery "+flow.ScreenName);}
 static IEnumerator Cases(){
 var region=skin.environmentBackgrounds.First(x=>x.firstFloor==91);Check(!region.playEntrance&&skin.EntranceForFloor(91)==null,"production entrance disabled");Check(region.throneEffects&&region.regionNumber==10&&Mathf.Approximately(region.entranceSeconds,2.8f),"prepared void transition data");
 foreach(EnvironmentScreen s in Enum.GetValues(typeof(EnvironmentScreen)))for(int f=91;f<=100;f++)Check(AssetDatabase.GetAssetPath(skin.BackgroundForScreen(f,s)).Contains("/Throne/"),"route "+f+" "+s);
 foreach(var set in skin.environmentBackgrounds.Where(x=>x.firstFloor<=90))foreach(EnvironmentScreen s in Enum.GetValues(typeof(EnvironmentScreen)))foreach(int f in new[]{set.firstFloor,set.lastFloor})Check(skin.BackgroundForScreen(f,s)==set.Get(s),"old route preserved "+f+" "+s);
 foreach(int f in new[]{101,110})Check(skin.BackgroundForFloor(f)==skin.forgeDepthsBackground&&skin.EntranceForFloor(f)==null,"beyond90 preserved "+f);
 Set(80,TowerRoomKind.Boss);var run=flow.CurrentRun;var cfg=FloorProgressionConfig.Load();run.BeginFloorCombat(cfg,80);Check(run.CompleteFloorCombat(run.MaxHP,cfg),"80 victory");Check(!run.CompleteFloorCombat(run.MaxHP,cfg),"80 duplicate settlement blocked");run.CompleteBattleRewards();run.AcknowledgeExperience();var snap=run.Capture();snap.PendingLevelAugments=0;snap.PendingEvolutionStage=0;Assign(TowerRun.Restore(snap,db));Call("AdvanceFloor");Check(flow.CurrentRun.Floor==80&&!flow.CurrentRun.Active&&flow.ScreenName=="타워 완주","80 completion not 91");yield return .2f;Capture("completion-80");
 Set(92,TowerRoomKind.Monster);Call("StartCurrentBattle");yield return .25f;Capture("battle-existing-monster-fixture");
 Set(100,TowerRoomKind.Boss);Call("Screen","보스 배경 미리보기");Call("RoomScenery","UI/boss-stairway",EnvironmentScreen.BossBattle);Scenery(EnvironmentScreen.BossBattle);var background=UnityEngine.Object.FindObjectsByType<Image>(FindObjectsSortMode.None).First(x=>x.name=="Room scenery"&&x.gameObject.activeInHierarchy);var fx=PrimordialThroneEnvironment.Create(background.rectTransform,Resources.Load<Sprite>("Environments/Throne/heart"));yield return .2f;Check(fx.ActiveGlyphCount==9&&fx.Corruption==0,"heart normal nine glyphs");Capture("heart-normal");Capture("boss-battle-preview");int hp=flow.CurrentRun.CurrentHP,heartGold=flow.CurrentRun.Gold;fx.TransitionTo(BondHeartState.Corrupted,.8f);yield return 1f;Check(fx.Corruption==1&&fx.ActiveGlyphCount==3,"heart corrupted dims six glyphs");Capture("heart-corrupted");fx.TransitionTo(BondHeartState.Recovering,2.4f);yield return 1.2f;Check(fx.ActiveGlyphCount>3&&fx.ActiveGlyphCount<9,"recovery sequential glyph activation");Capture("heart-recovering");yield return 1.4f;Check(fx.Corruption==0&&fx.ActiveGlyphCount==9&&fx.TransitionProgress==1,"heart recovery complete");Capture("heart-recovered");fx.TransitionTo(BondHeartState.Corrupted,2);yield return .1f;fx.TransitionTo(BondHeartState.Normal,.1f);yield return .2f;Check(fx.State==BondHeartState.Normal&&fx.Corruption==0,"heart transition interruption");Check(flow.CurrentRun.CurrentHP==hp&&flow.CurrentRun.Gold==heartGold&&flow.CurrentRun.Floor==100,"heart has no gameplay effects");Check(background.sprite==skin.BackgroundForScreen(100,EnvironmentScreen.BossBattle)&&background.sprite!=skin.BackgroundForFloor(99),"100 arena distinct from corridor");
 Set(92,TowerRoomKind.Item);Call("ShowTreasureChamber");Scenery(EnvironmentScreen.Item);yield return .2f;Capture("item");flow.RoomButton.onClick.Invoke();flow.RoomButton.onClick.Invoke();yield return 2f;Check(flow.CurrentRun.ChestOpened&&flow.ChoiceButtons.Length==3,"chest three rewards");var ids=string.Join(",",flow.CurrentRun.ChestRewardIds);Call("SaveProgress");flow.ShowLobby();flow.ResumeRun();Check(string.Join(",",flow.CurrentRun.ChestRewardIds)==ids,"fixture chest resume");
 Set(93,TowerRoomKind.Gold);Call("ShowGoldRoom");Scenery(EnvironmentScreen.Item);yield return .2f;Capture("gold");flow.RoomButton.onClick.Invoke();flow.RoomButton.onClick.Invoke();yield return 1.25f;Check(flow.CurrentRun.Gold==50,"gold once");
 Set(94,TowerRoomKind.Recovery);flow.CurrentRun.SyncHealth(1,false);Call("ShowRecoveryRoom");Scenery(EnvironmentScreen.Item);yield return .2f;Capture("recovery");flow.RoomButton.onClick.Invoke();yield return 1.25f;Check(flow.CurrentRun.CurrentHP==flow.CurrentRun.MaxHP,"heal maintained");
 Set(95,TowerRoomKind.Nest);Call("ShowNestRoom");Scenery(EnvironmentScreen.Item);yield return .2f;Capture("nest");int owned=flow.Session.Profile.dragons.Count;flow.RoomButton.onClick.Invoke();flow.RoomButton.onClick.Invoke();yield return 1.3f;Check(flow.Session.Profile.dragons.Count==owned+1,"nest once");
 Set(92,TowerRoomKind.Item,false);Call("ShowTowerChoices");Scenery(EnvironmentScreen.Stairs);yield return .2f;Capture("stairs");Check(flow.RoomButton.GetComponent<RectTransform>().anchoredPosition==new Vector2(-103,-225),"door target unchanged");flow.RoomButton.onClick.Invoke();yield return 1.4f;Check(flow.ScreenName=="아이템방","fixture door selection");
 Set(100,TowerRoomKind.Boss,false);Call("ShowTowerChoices");Scenery(EnvironmentScreen.BossEntrance);yield return .2f;Capture("boss-entrance");
 Set(91,TowerRoomKind.Item,false);Call("ShowTowerChoices");Check(flow.ScreenName=="다음 길 선택","no automatic 91 entrance even in fixture");int gold=flow.CurrentRun.Gold,score=flow.CurrentRun.Progress.score;flow.StartCoroutine((IEnumerator)Call("ShowRegionEntrance",region,skin));yield return .85f;Check(UnityEngine.Object.FindFirstObjectByType<RegionWaterParticles>().throne,"throne prepared effects");Capture("transition-door");yield return .55f;Capture("transition-stairs");yield return .9f;Capture("transition-title");yield return 1f;Check(flow.CurrentRun.Floor==91&&flow.CurrentRun.Gold==gold&&flow.CurrentRun.Progress.score==score,"preview presentation no progression or rewards");
 Set(91,TowerRoomKind.Item,false);flow.StartCoroutine((IEnumerator)Call("ShowRegionEntrance",region,skin));yield return .1f;var skip=UnityEngine.Object.FindObjectsByType<Button>(FindObjectsSortMode.None).First(x=>x.name=="Region skip"&&x.gameObject.activeInHierarchy);skip.onClick.Invoke();skip.onClick.Invoke();yield return .1f;Check(flow.CurrentRun.Floor==91&&flow.ScreenName=="다음 길 선택","preview repeated skip");Check(!region.playEntrance&&skin.EntranceForFloor(91)==null,"preview never enabled production entry");
 foreach(string species in new[]{"제피르","단테","루나"}){flow.ShowLobby();int index=Array.FindIndex(db.dragons,d=>d.displayName==species);flow.Session.Profile.eggs++;flow.Session.Hatch(index);Set(92,TowerRoomKind.Monster);Call("StartCurrentBattle");yield return .25f;string slug=species=="제피르"?"zephyr":species=="단테"?"dante":"luna";Capture("battle-"+slug);Check(UnityEngine.Object.FindFirstObjectByType<BattleController>().CurrentBattle.Skill(),"existing skill accepted "+species);yield return .06f;Capture("skill-"+slug);}
 Debug.Log("THRONE_ALL_OK");yield return .1f;
 }
 static void Tick(){try{if(!EditorApplication.isPlaying||EditorApplication.timeSinceStartup<next)return;if(flow==null){flow=UnityEngine.Object.FindFirstObjectByType<CollectionFlow>();if(flow?.Session==null){flow=null;return;}if(flow.Session.Selected==null)flow.Session.Hatch(0);db=ContentDatabase.Load();skin=Resources.Load<BattleSkin>("PixelBattleSkin");Screen.SetResolution(480,850,false);cases=Cases();}if(cases.MoveNext()){next=EditorApplication.timeSinceStartup+(float)cases.Current;return;}SessionState.SetBool(Flag,false);EditorApplication.Exit(0);}catch(Exception e){Debug.LogException(e);SessionState.SetBool(Flag,false);EditorApplication.Exit(1);}}
}}



